def score(facts: Mapping[str, object]) -> float:
    node = 0
    while True:
        feature_index, threshold, left, right, value = NODES[node]
        if left < 0:
            return value
        if _feature_value(FEATURES[feature_index], facts) <= threshold:
            node = left
        else:
            node = right


def _feature_value(feature: tuple[str, str] | tuple[str, str, str], facts: Mapping[str, object]) -> float:
    kind = feature[0]
    if kind == "cat":
        _kind, field, expected = feature
        return 1.0 if str(facts.get(field, "")) == expected else 0.0
    _kind, field = feature
    value = facts.get(field, -1.0)
    try:
        return float(value)
    except (TypeError, ValueError):
        return -1.0
